async function inner() {
  console.log("inner");
  return 1;
}

async function outer() {
  console.log("outer start");
  const value = await inner();
  console.log("outer got " + value);
}

outer();
Promise.resolve()
  .then(() => console.log("then A"))
  .then(() => console.log("then B"));
console.log("end");
